"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { Input } from "@/components/ui/input"

/** Newsletter signup: email field, submit button and a short consent line. */
export default function Newsletter({
  heading = "Stay in the loop",
  description = "One short email when something new ships.",
  emailLabel = "Email address",
  submitLabel = "Subscribe",
  consent = "We only use your email for this newsletter. Unsubscribe any time.",
  onSubmit,
}: {
  heading?: string
  description?: string
  emailLabel?: string
  submitLabel?: string
  consent?: string
  onSubmit?: (email: string) => void
}) {
  const id = React.useId()
  const [email, setEmail] = React.useState("")
  return (
    <section data-slot="newsletter" className="py-12">
      <div className="mx-auto max-w-xl px-6 text-center">
        <h2 className="font-heading text-2xl font-semibold tracking-tight">{heading}</h2>
        <p className="mt-2 text-muted-foreground">{description}</p>
        <form
          className="mt-6 flex flex-col gap-2 sm:flex-row"
          onSubmit={(e) => {
            e.preventDefault()
            onSubmit?.(email)
          }}
        >
          <label htmlFor={id} className="sr-only">
            {emailLabel}
          </label>
          <Input id={id} type="email" required autoComplete="email" placeholder={emailLabel} value={email} onChange={(e) => setEmail(e.target.value)} className="sm:flex-1" aria-describedby={`${id}-consent`} />
          <Button type="submit">
            {submitLabel}
            <Icon name="arrow-right" data-icon="inline-end" />
          </Button>
        </form>
        <p id={`${id}-consent`} className="mt-3 text-xs text-muted-foreground">
          {consent}
        </p>
      </div>
    </section>
  )
}
